//! Replays the picoclaw fixtures against this crate.
//!
//! Run with `cargo test --test conformance`. The corpus is generated by Go code,
//! so a failure means one of two things: the Rust port drifted, or the Go
//! behaviour changed on purpose and the fixtures are stale. `conformance/README.md`
//! says how to tell which, and which one to fix.

use std::collections::BTreeMap;

use conformance::{Fixture, Report};
use crab_tokenizer::go_json::{self, Value as GoValue};
use crab_tokenizer::{
    ContentBlock, FunctionCall, Message, ToolCall, ToolDefinition, ToolFunctionDefinition,
};
use serde_json::{json, Value};

/// The marker `cmd/oracle` writes for a value Go's `json.Marshal` refuses. It
/// cannot be represented in JSON, and the estimator's behaviour on it -- skip the
/// whole enclosing map -- is not the same as encoding the fields that were fine.
const MARSHAL_ERROR: &str = "$go_marshal_error";

#[test]
fn estimate_message_tokens_matches_go() {
    let fixture = Fixture::load("tokenizer_estimate_message_tokens.json");
    let mut report = Report::new(&fixture);

    for case in &fixture.cases {
        let input: FixtureMessage = case.parse();
        let got = crab_tokenizer::estimate_message_tokens(&input.into_message());
        report.record(case, json!(got));
    }

    report.finish(12);
}

#[test]
fn estimate_tool_defs_tokens_matches_go() {
    let fixture = Fixture::load("tokenizer_estimate_tool_defs_tokens.json");
    let mut report = Report::new(&fixture);

    for case in &fixture.cases {
        let input: FixtureToolDefs = case.parse();
        let got = crab_tokenizer::estimate_tool_defs_tokens(&input.into_defs());
        report.record(case, json!(got));
    }

    report.finish(12);
}

/// The encoder seam above only reaches `json.Marshal` through a token count, so a
/// one-byte difference would surface as an off-by-one estimate and say nothing
/// about which byte moved. This one compares the bytes.
#[test]
fn encode_matches_go_json_marshal() {
    let fixture = Fixture::load("go_json_encode_parameters.json");
    let mut report = Report::new(&fixture);

    for case in &fixture.cases {
        let input: FixtureParam = case.parse();
        let got = match &input.parameters {
            Some(v) => match go_json::marshal(&to_go_value(v)) {
                Ok(bytes) => json!(String::from_utf8_lossy(&bytes).to_string()),
                // Go's json.Marshal returns "" plus an error in this case, and
                // the fixture records that as null.
                Err(_) => Value::Null,
            },
            // A nil interface marshals to the four bytes `null`; it is not an
            // error and not the same as an absent field.
            None => json!("null"),
        };
        report.record(case, got);
    }

    report.finish(12);
}

// ------------------------------------------------------------- message input --

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureMessage {
    content: String,
    reasoning_content: String,
    system_parts: Vec<FixturePart>,
    tool_calls: Vec<FixtureToolCall>,
    tool_call_id: String,
    /// The estimator only counts media items, so the fixture records a count
    /// instead of inventing paths that would imply the contents matter.
    media_count: usize,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixturePart {
    #[serde(rename = "type")]
    part_type: String,
    text: String,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureToolCall {
    id: String,
    #[serde(rename = "type")]
    call_type: String,
    name: String,
    function: Option<FixtureFunctionCall>,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureFunctionCall {
    name: String,
    arguments: String,
}

impl FixtureMessage {
    fn into_message(self) -> Message {
        Message {
            role: "user".into(),
            content: self.content,
            reasoning_content: self.reasoning_content,
            system_parts: self
                .system_parts
                .into_iter()
                .map(|p| ContentBlock {
                    part_type: p.part_type,
                    text: p.text,
                })
                .collect(),
            tool_calls: self
                .tool_calls
                .into_iter()
                .map(|tc| ToolCall {
                    id: tc.id,
                    call_type: tc.call_type,
                    function: tc.function.map(|f| FunctionCall {
                        name: f.name,
                        arguments: f.arguments,
                    }),
                    name: tc.name,
                })
                .collect(),
            tool_call_id: self.tool_call_id,
            media: (0..self.media_count).map(|i| format!("media-{i}")).collect(),
        }
    }
}

// ---------------------------------------------------------- tool defs input --

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureToolDefs {
    defs: Vec<FixtureToolDef>,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureToolDef {
    name: String,
    description: String,
    parameters: Option<Value>,
}

impl FixtureToolDefs {
    fn into_defs(self) -> Vec<ToolDefinition> {
        self.defs
            .into_iter()
            .map(|d| ToolDefinition {
                def_type: "function".into(),
                function: ToolFunctionDefinition {
                    name: d.name,
                    description: d.description,
                    parameters: d.parameters.map(|p| to_go_value(&p)),
                },
            })
            .collect()
    }
}

// ------------------------------------------------------------ encoder input --

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureParam {
    /// `null` in the fixture means Go's nil interface, which marshals to the
    /// literal `null`; an absent key would mean something else, so this is
    /// `Option` rather than `Value` and the field is required.
    parameters: Option<Value>,
}

// --------------------------------------------------------------- value mapping --

/// Maps a fixture value onto the value model Go's `map[string]any` can hold.
fn to_go_value(v: &Value) -> GoValue {
    match v {
        Value::Null => GoValue::Null,
        Value::Bool(b) => GoValue::Bool(*b),
        Value::String(s) => GoValue::Str(s.clone()),
        Value::Number(n) => go_number(n),
        Value::Array(items) => GoValue::Array(items.iter().map(to_go_value).collect()),
        Value::Object(map) => {
            if let Some(kind) = marshal_error_marker(map) {
                return GoValue::Unsupported(kind);
            }
            let mut out = BTreeMap::new();
            for (k, val) in map {
                out.insert(k.clone(), to_go_value(val));
            }
            GoValue::Object(out)
        }
    }
}

/// A JSON number that came from Go is either an integer kind or a float, and the
/// fixture cannot tell them apart -- Go writes `float64(7)` as `7`, exactly as it
/// writes `int(7)`. That is harmless for every value except negative zero: Go
/// writes `float64(-0.0)` as `-0`, which JSON parses back to the integer `0`, and
/// `0` encodes to one byte instead of two.
///
/// Floats go through [`serde_json::Number::as_f64`], which is only correctly
/// rounded because the workspace enables serde_json's `arbitrary_precision`
/// feature. Without it serde_json accumulates decimal digits straight into an
/// `f64`, which lands one ULP away from the correct value on some
/// shortest-round-trip literals: with the feature off this suite reported 27
/// encoder mismatches across 676 encoded parameter values, every one of them the
/// harness mis-parsing the fixture rather than the port encoding wrongly. Any code
/// here that turns provider JSON into an `f64` needs the same feature, or it will
/// disagree with Go about which number it has.
fn go_number(n: &serde_json::Number) -> GoValue {
    if n.to_string() == "-0" {
        return GoValue::Float(-0.0);
    }
    if let Some(i) = n.as_i64() {
        return GoValue::Int(i);
    }
    if let Some(u) = n.as_u64() {
        return GoValue::UInt(u);
    }
    GoValue::Float(n.as_f64().expect("a JSON number is representable as f64"))
}

fn marshal_error_marker(map: &serde_json::Map<String, Value>) -> Option<&'static str> {
    if map.len() != 1 {
        return None;
    }
    match map.get(MARSHAL_ERROR) {
        Some(Value::String(kind)) => Some(leak(kind)),
        _ => None,
    }
}

/// [`go_json::Value::Unsupported`] carries a `&'static str` so the value type
/// stays cheap to clone; fixture strings live for the whole test run anyway.
fn leak(s: &str) -> &'static str {
    Box::leak(s.to_string().into_boxed_str())
}
